// Generates the lucide subsets the kit renders, so importing a component no
// longer pulls the whole collection. Run as part of the build; a new
// "lucide:..." literal in src is picked up automatically. Each row of SETS is
// one generated file: the editor's icons ship with the editor entry only, so a
// plain LpIcon does not carry them.
import { readFileSync, writeFileSync } from "node:fs"
import { createRequire } from "node:module"
import { dirname, resolve } from "node:path"
import { fileURLToPath } from "node:url"
import { namesInDirs, subset } from "../src/iconSubset.mjs"

const here = dirname(fileURLToPath(import.meta.url))
const require = createRequire(import.meta.url)
const src = resolve(here, "../src")
const editor = resolve(src, "editor")

const SETS = [
  { name: "KIT_ICONS", out: resolve(src, "kit-icons.ts"), dirs: [src], skip: [editor], minus: [] },
  { name: "EDITOR_ICONS", out: resolve(editor, "editor-icons.ts"), dirs: [editor], skip: [], minus: ["KIT_ICONS"] },
]

const lucide = JSON.parse(readFileSync(require.resolve("@iconify-json/lucide/icons.json"), "utf8"))
const written = new Map()
for (const set of SETS) {
  const names = namesInDirs(set.dirs, set.skip)
  for (const other of set.minus) for (const name of written.get(other) ?? []) names.delete(name)
  const data = subset(lucide, names)
  const missing = [...names].filter((n) => !data.icons[n] && !data.aliases?.[n])
  if (missing.length) {
    console.error(`gen-kit-icons: unknown lucide icons: ${missing.join(", ")}`)
    process.exit(1)
  }
  written.set(set.name, names)
  writeFileSync(
    set.out,
    `/* AUTO-GENERATED by scripts/gen-kit-icons.mjs — do not edit.
 * The lucide icons kit components render, registered offline by icons.ts. */
import type { IconifyJSON } from "@iconify/vue"

export const ${set.name}: IconifyJSON = ${JSON.stringify(data)}
`,
  )
  console.log(`gen-kit-icons: wrote ${Object.keys(data.icons).length} icons to ${set.name}`)
}
